import{_ as t,c as r,o,ag as a,j as i}from"./chunks/framework.DfL_BkQ-.js";const m=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/installation.md","filePath":"fr/guide/installation.md","lastUpdated":1794112334000}'),n={name:"fr/guide/installation.md"};function s(l,e,c,d,u,p){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><h2 id="telecharger-nicasa" tabindex="-1">Télécharger Nicasa <a class="header-anchor" href="#telecharger-nicasa" aria-label="Permalink to &quot;Télécharger Nicasa&quot;">​</a></h2><p>Nicasa est disponible exclusivement pour macOS via le Mac App Store. L&#39;application coûte 4,99 $ et propose un achat unique donnant accès à toutes les fonctionnalités.</p><h3 id="options-de-telechargement" tabindex="-1">Options de téléchargement <a class="header-anchor" href="#options-de-telechargement" aria-label="Permalink to &quot;Options de téléchargement&quot;">​</a></h3><ul><li><strong>Mac App Store</strong> : <a href="https://apps.apple.com/us/app/nicasa-image-viewer/id6756032669?mt=12" target="_blank" rel="noreferrer">Télécharger Nicasa</a> —— 4,99 $</li><li><strong>Extension Chrome</strong> : <a href="https://chromewebstore.google.com/detail/nicasa-image-viewer/cihceekeiedkinpjjjfehlgjdhpeokbj" target="_blank" rel="noreferrer">Extension Chrome gratuite</a> —— Gratuit</li></ul><h2 id="etapes-d-installation" tabindex="-1">Étapes d&#39;installation <a class="header-anchor" href="#etapes-d-installation" aria-label="Permalink to &quot;Étapes d&#39;installation&quot;">​</a></h2><h3 id="installation-via-le-mac-app-store" tabindex="-1">Installation via le Mac App Store <a class="header-anchor" href="#installation-via-le-mac-app-store" aria-label="Permalink to &quot;Installation via le Mac App Store&quot;">​</a></h3><ol><li>Cliquez sur le lien « Télécharger Nicasa » ci-dessus ou recherchez « Nicasa » dans le Mac App Store</li><li>Cliquez sur « Obtenir » ou « Acheter » pour acquérir l&#39;application (4,99 $)</li><li>L&#39;application se télécharge et s&#39;installe automatiquement</li><li>Lancez Nicasa depuis le dossier Applications ou le Launchpad</li></ol><h3 id="installation-de-l-extension-chrome" tabindex="-1">Installation de l&#39;extension Chrome <a class="header-anchor" href="#installation-de-l-extension-chrome" aria-label="Permalink to &quot;Installation de l&#39;extension Chrome&quot;">​</a></h3><ol><li>Rendez-vous sur la <a href="https://chromewebstore.google.com/detail/nicasa-image-viewer/cihceekeiedkinpjjjfehlgjdhpeokbj" target="_blank" rel="noreferrer">page du Chrome Web Store</a></li><li>Cliquez sur « Ajouter à Chrome »</li><li>Confirmez l&#39;installation dans la fenêtre qui s&#39;ouvre</li><li>L&#39;extension est ajoutée à votre navigateur</li></ol><h4 id="demonstration-de-l-extension-chrome" tabindex="-1">Démonstration de l&#39;extension Chrome <a class="header-anchor" href="#demonstration-de-l-extension-chrome" aria-label="Permalink to &quot;Démonstration de l&#39;extension Chrome&quot;">​</a></h4>',11),i("div",{style:{position:"relative","padding-bottom":"56.25%",height:"0"}},[i("iframe",{src:"https://www.youtube.com/embed/NJPweIr1J4s",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:"",style:{position:"absolute",top:"0",left:"0",width:"100%",height:"100%"}})],-1),a('<p><a href="https://www.youtube.com/watch?v=NJPweIr1J4s" target="_blank" rel="noopener">Regarder : démonstration rapide de l&#39;extension Chrome Nicasa</a></p><h2 id="premier-lancement" tabindex="-1">Premier lancement <a class="header-anchor" href="#premier-lancement" aria-label="Permalink to &quot;Premier lancement&quot;">​</a></h2><p>Lors du premier lancement de Nicasa :</p><ol><li>Il vous sera demandé d&#39;accorder les autorisations nécessaires (enregistrement de l&#39;écran pour les captures)</li><li>L&#39;application analyse votre dossier Images à la recherche d&#39;images</li><li>Vous pouvez immédiatement parcourir votre collection</li><li>Pensez à installer l&#39;extension Chrome pour améliorer la navigation web</li></ol><h3 id="extension-de-synchronisation-finder" tabindex="-1">Extension de synchronisation Finder <a class="header-anchor" href="#extension-de-synchronisation-finder" aria-label="Permalink to &quot;Extension de synchronisation Finder&quot;">​</a></h3><p>Nicasa inclut une extension de barre d&#39;outils du Finder pour traiter rapidement vos images :</p><ol><li>Après avoir lancé Nicasa, allez dans <strong>Réglages Système</strong> → <strong>Extensions</strong> → <strong>Extensions du Finder</strong></li><li>Activez <strong>Nicasa Finder Sync</strong></li><li>Faites un clic droit sur la barre d&#39;outils du Finder → <strong>Personnaliser la barre d&#39;outils…</strong></li><li>Faites glisser le bouton Nicasa dans la barre d&#39;outils</li></ol><p>Vous pourrez ainsi optimiser ou éditer les images sélectionnées directement depuis le Finder.</p><h2 id="configuration-requise" tabindex="-1">Configuration requise <a class="header-anchor" href="#configuration-requise" aria-label="Permalink to &quot;Configuration requise&quot;">​</a></h2><ul><li><strong>macOS</strong> : 10.13 ou version ultérieure</li><li><strong>Stockage</strong> : 54,5 Mo d&#39;espace disponible</li><li><strong>Mémoire</strong> : 4 Go de RAM minimum, 8 Go recommandés</li></ul><h2 id="autorisations" tabindex="-1">Autorisations <a class="header-anchor" href="#autorisations" aria-label="Permalink to &quot;Autorisations&quot;">​</a></h2><p>Nicasa nécessite les autorisations suivantes :</p><ul><li><strong>Enregistrement de l&#39;écran</strong> : pour la fonction de capture (peut être accordée plus tard)</li><li><strong>Accessibilité</strong> : pour les fonctions du mode superposition (facultatif)</li><li><strong>Fichiers et dossiers</strong> : accès au dossier Images et aux répertoires choisis par l&#39;utilisateur</li></ul><p>Vous pouvez modifier ces autorisations à tout moment dans Réglages Système &gt; Confidentialité et sécurité.</p><h2 id="depannage-de-l-installation" tabindex="-1">Dépannage de l&#39;installation <a class="header-anchor" href="#depannage-de-l-installation" aria-label="Permalink to &quot;Dépannage de l&#39;installation&quot;">​</a></h2><p>Si vous rencontrez des problèmes lors de l&#39;installation :</p><ul><li>Vérifiez que vous disposez des privilèges administrateur/root</li><li>Vérifiez que votre système répond à la configuration minimale</li><li>Essayez de télécharger à nouveau le fichier</li><li>Sous Linux, vérifiez que les dépendances requises sont installées</li></ul><p>Pour plus d&#39;aide, consultez notre <a href="https://github.com/nicasa-project/nicasa-support/issues" target="_blank" rel="noreferrer">page des problèmes</a>.</p>',18)])])}const g=t(n,[["render",s]]);export{m as __pageData,g as default};
